private void enlarge(final int size) {
    // Validate input
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return; // nothing to do
    }

    // Current state
    int currentSize = this.size;          // number of bytes currently stored
    int currentCapacity = this.capacity;  // current array capacity

    // Compute the required capacity as a long to detect overflow
    long requiredLong = (long) currentSize + size;
    if (requiredLong > Integer.MAX_VALUE) {
        requiredLong = Integer.MAX_VALUE;
    }

    // If the current capacity is already sufficient, nothing to do
    if (requiredLong <= currentCapacity) {
        return;
    }

    // Determine new capacity: at least required, but grow by doubling strategy
    long doubled = (long) currentCapacity * 2;
    long newCapacityLong = Math.max(requiredLong, doubled);
    if (newCapacityLong > Integer.MAX_VALUE) {
        newCapacityLong = Integer.MAX_VALUE;
    }
    int newCapacity = (int) newCapacityLong;

    // Allocate new array and copy existing data
    try {
        byte[] newBytes = new byte[newCapacity];
        if (this.bytes != null && currentSize > 0) {
            System.arraycopy(this.bytes, 0, newBytes, 0, currentSize);
        }
        this.bytes = newBytes;
        this.capacity = newCapacity;
    } catch (OutOfMemoryError e) {
        throw new IllegalStateException("Unable to enlarge byte vector", e);
    }
}

