                char next = patternStr.charAt(i + 1);
                if (next == '%') {
                    sb.append('%');
                    i += 2;
                    continue;
                }
                switch (next) {
                    case 'd':
                        String dateFormat = "yyyy-MM-dd HH:mm:ss.SSS";
                        int start = i + 2;
                        if (start < patternStr.length() && patternStr.charAt(start) == '{') {
                            int end = patternStr.indexOf('}', start);
                            if (end != -1) {
                                dateFormat = patternStr.substring(start + 1, end);
                                i = end + 1;
