void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }

    // Detach this bucket from its current neighbors, if any
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }

    // Insert this bucket before the specified bucket
    this.prev = bucket.prev;
    this.next = bucket;
    if (bucket.prev != null) {
        bucket.prev.next = this;
    }
    bucket.prev = this;
}

