public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("tableName cannot be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("mappings cannot be null");
    }
    try {
        // Retrieve the current mapping for the given table name.
        // It is assumed that a MappingService (or similar) exists to provide this.
        Mappings current = MappingService.getMapping(tableName);
        if (current == null) {
            return null;
        }

        java.util.Map<String, Object> currentProps = current.getProperties();
        java.util.Map<String, Object> historyProps = mappings.getProperties();

        java.util.Map<String, Object> diffProps = new java.util.LinkedHashMap<>();
        for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            // Skip the _source field to avoid update conflicts.
            if ("_source".equals(field)) {
                continue;
            }
            if (!historyProps.containsKey(field)) {
                diffProps.put(field, entry.getValue());
            }
        }

        Mappings diff = new Mappings();
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute diff structure", e);
    }
}

