    }
    // Ensure the requested slice is within bounds of the provided array
    if (offset > data.length - len) {
        return false;
    }
    // Check that the internal array exists and has the expected length
    if (this.array == null || this.array.length != len) {
        return false;
    }
    // Compare byte by byte
