static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate inputs
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be a positive long representing a date in YYYYMMDD format");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }

    // Extract year, month, day from the long value
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Basic sanity checks for month and day
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    // Compute the compressed day based on dayStep
    int newDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the compressed date as a long in YYYYMMDD format
    return (long) year * 10000L + (long) month * 100L + (long) newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (len < 0) {
        throw new IllegalArgumentException("len must be non-negative");
    }
    long endLong = (long) index + len;
    if (index < 0 || endLong > str.length()) {
        throw new IndexOutOfBoundsException("index and len out of bounds");
    }
    int end = (int) endLong;
    long size = 0;
    for (int i = index; i < end; ) {
        char c = str.charAt(i);
        if (Character.isHighSurrogate(c) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            int codePoint = Character.toCodePoint(c, str.charAt(i + 1));
            i += 2;
            if (codePoint <= 0x7F) {
                size += 1;
            } else if (codePoint <= 0x7FF) {
                size += 2;
            } else if (codePoint <= 0xFFFF) {
                size += 3;
            } else {
                size += 4;
            }
        } else if (Character.isSurrogate(c)) {
            // lone surrogate, encode as replacement character U+FFFD (3 bytes)
            size += 3;
            i++;
        } else {
            if (c <= 0x7F) {
                size += 1;
            } else if (c <= 0x7FF) {
                size += 2;
            } else {
                size += 3;
            }
            i++;
        }
        if (size > Integer.MAX_VALUE) {
            throw new ArithmeticException("UTF-8 size exceeds int range");
        }
    }
    return (int) size;
}

