public void removeFromTreeEdgeList() {
    try {
        // Remove this edge from the source node's tree edge list
        if (source != null) {
            if (prevTreeEdge != null) {
                prevTreeEdge.nextTreeEdge = nextTreeEdge;
            } else {
                source.firstTreeEdge = nextTreeEdge;
            }
            if (nextTreeEdge != null) {
                nextTreeEdge.prevTreeEdge = prevTreeEdge;
            } else {
                source.lastTreeEdge = prevTreeEdge;
            }
        }

        // Remove this edge from the destination node's tree edge list
        if (dest != null) {
            if (prevTreeEdgeDest != null) {
                prevTreeEdgeDest.nextTreeEdgeDest = nextTreeEdgeDest;
            } else {
                dest.firstTreeEdge = nextTreeEdgeDest;
            }
            if (nextTreeEdgeDest != null) {
                nextTreeEdgeDest.prevTreeEdgeDest = prevTreeEdgeDest;
            } else {
                dest.lastTreeEdge = prevTreeEdgeDest;
            }
        }

        // Nullify this edge's own pointers
        prevTreeEdge = nextTreeEdge = null;
        prevTreeEdgeDest = nextTreeEdgeDest = null;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to remove edge from tree edge list", e);
    }
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("key and props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    String result = value;
    final int MAX_DEPTH = 10;
    for (int depth = 0; depth < MAX_DEPTH; depth++) {
        java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}").matcher(result);
        boolean found = false;
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            found = true;
            String subKey = matcher.group(1);
            String subVal = props.getProperty(subKey);
            if (subVal == null) {
                subVal = "";
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(subVal));
        }
        matcher.appendTail(sb);
        result = sb.toString();
        if (!found) {
            break;
        }
    }
    return result;
}

