public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    double minX = box.getMinX();
    double minY = box.getMinY();
    double maxX = box.getMaxX();
    double maxY = box.getMaxY();

    if (minX > maxX) {
        throw new IllegalArgumentException("box minX is greater than maxX");
    }
    if (minY > maxY) {
        throw new IllegalArgumentException("box minY is greater than maxY");
    }

    double midX = (minX + maxX) / 2.0;
    Box2D left = new Box2D(minX, minY, midX, maxY);
    Box2D right = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(left, right);
}

private void enlarge(final int size) {
    if (size <= 0) {
        return; // nothing to enlarge
    }
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non‑negative");
    }
    // If the internal buffer is null, create a new one of the required size
    if (buf == null) {
        buf = new byte[size];
        return;
    }
    // Compute the new capacity: double the current size or add the requested size,
    // whichever is larger, to reduce the number of resizes.
    int newCapacity = Math.max(buf.length * 2, buf.length + size);
    // Guard against integer overflow
    if (newCapacity < 0) {
        throw new OutOfMemoryError("Required array size too large");
    }
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buf, 0, newBuf, 0, buf.length);
    buf = newBuf;
}

