    if (name.length() > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (name.length() == 1) {
        return String.valueOf(upperFirst);
    }
    return upperFirst + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Determine how many bytes to write from this node
        int len = current.pos;
        if (len < 0) {
            len = 0;
        } else if (len > current.buf.length) {
            len = current.buf.length;
        }
        if (len > 0) {
            out.write(current.buf, 0, len);
            total += len;
        }
        current = current.next;
    }
    return total;
}

