public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("[");
    try {
        // If the queue implements Iterable, use its iterator
        if (this instanceof java.lang.Iterable) {
            java.util.Iterator<?> it = ((java.lang.Iterable<?>) this).iterator();
            while (it.hasNext()) {
                Object elem = it.next();
                sb.append(elem);
                if (it.hasNext()) sb.append(", ");
            }
        } else {
            // Attempt to find a field that holds the queue elements
            java.lang.reflect.Field[] fields = this.getClass().getDeclaredFields();
            boolean found = false;
            for (java.lang.reflect.Field f : fields) {
                f.setAccessible(true);
                Object val = f.get(this);
                if (val == null) continue;
                // Handle collections
                if (val instanceof java.util.Collection) {
                    java.util.Collection<?> col = (java.util.Collection<?>) val;
                    java.util.Iterator<?> it = col.iterator();
                    while (it.hasNext()) {
                        Object elem = it.next();
                        sb.append(elem);
                        if (it.hasNext()) sb.append(", ");
                    }
                    found = true;
                    break;
                }
                // Handle arrays
                if (val.getClass().isArray()) {
                    int len = java.lang.reflect.Array.getLength(val);
                    for (int i = 0; i < len; i++) {
                        Object elem = java.lang.reflect.Array.get(val, i);
                        sb.append(elem);
                        if (i < len - 1) sb.append(", ");
                    }
                    found = true;
                    break;
                }
                // Handle linked list node chain (fields named data/next)
                try {
                    java.lang.reflect.Field nextField = val.getClass().getDeclaredField("next");
                    java.lang.reflect.Field dataField = val.getClass().getDeclaredField("data");
                    nextField.setAccessible(true);
                    dataField.setAccessible(true);
                    Object node = val;
                    java.util.Set<Object> visited = new java.util.HashSet<>();
                    while (node != null && !visited.contains(node)) {
                        visited.add(node);
                        Object data = dataField.get(node);
                        sb.append(data);
                        node = nextField.get(node);
                        if (node != null) sb.append(", ");
                    }
                    found = true;
                    break;
                } catch (NoSuchFieldException e) {
                    // Not a node chain, continue searching
                }
            }
            if (!found) {
                // Fallback to default representation
                sb.append(this.getClass().getName()).append("@")
                  .append(Integer.toHexString(System.identityHashCode(this)));
            }
        }
    } catch (Exception e) {
        sb.append("Error: ").append(e.getMessage());
    }
    sb.append("]");
    return sb.toString();
}

