        StringBuilder sb = new StringBuilder();
        // Timestamp
        sb.append(new java.util.Date(event.getTimeStamp()).toString());
        sb.append(" [");
        java.lang.Object levelObj = event.getLevel();
        sb.append(levelObj != null ? levelObj.toString() : "UNKNOWN");
        sb.append("] ");
        // Thread name
        sb.append(event.getThreadName() != null ? event.getThreadName() : "UNKNOWN");
        sb.append(" - ");
        // Logger name
        sb.append(event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN");
        sb.append(" - ");
        // Message
        sb.append(String.valueOf(event.getMessage()));
        // Throwable information
        if (event.getThrowableInformation() != null) {
            java.io.StringWriter sw = new java.io.StringWriter();
            java.io.PrintWriter pw = new java.io.PrintWriter(sw);
            event.getThrowableInformation().getThrowable().printStackTrace(pw);
            pw.flush();
            sb.append(System.lineSeparator());
            sb.append(sw.toString());
        }
        return sb.toString();
    } catch (Exception e) {
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

