    }
    return result;
}

private void addInitializedType(final int abstractType) {
    // Validate input
    if (abstractType < 0) {
        throw new IllegalArgumentException("abstractType must be non-negative");
    }
    try {
        // Lazily initialize the collection if necessary
        if (initializedTypes == null) {
            initializedTypes = new java.util.HashSet<>();
        }
        // Add the type to the set (duplicates are ignored)
        initializedTypes.add(abstractType);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Failed to add initialized type", e);
    }
}

private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null || stackMapTableEntries == null) {
        throw new IllegalStateException("Frame or stack map table entries not initialized");
    }
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start/end indices");
    }
    try {
        for (int i = start; i < end; i++) {
            AbstractType type = currentFrame[i];
            if (type == null) {
                throw new IllegalArgumentException("Null type at index " + i);
            }
            int tag = type.getTag();
            stackMapTableEntries[stackMapTableEntriesIndex++] = (byte) tag;
            switch (tag) {
                case 7: // ITEM_Object
                    int classIndex = type.getClassIndex();
                    stackMapTableEntries[stackMapTableEntriesIndex++] = (byte) ((classIndex >> 8) & 0xFF);
                    stackMapTableEntries[stackMapTableEntriesIndex++] = (byte) (classIndex & 0xFF);
                    break;
                case 8: // ITEM_Uninitialized
                    int offset = type.getOffset();
                    stackMapTableEntries[stackMapTableEntriesIndex++] = (byte) ((offset >> 8) & 0xFF);
                    stackMapTableEntries[stackMapTableEntriesIndex++] = (byte) (offset & 0xFF);
                    break;
                default:
                    // No additional bytes for other tags
                    break;
            }
        }
    } catch (ArrayIndexOutOfBoundsException | NullPointerException e) {
        throw new IllegalStateException("Failed to write abstract types to stack map table", e);
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new NullPointerException("InputStream cannot be null");
    }
    // Read all bytes from the input stream
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] tmp = new byte[8192];
    int n;
    while ((n = in.read(tmp)) != -1) {
        baos.write(tmp, 0, n);
    }
    byte[] data = baos.toByteArray();

    // Clear the existing buffer and load the new data
    this.buffer = data;
    this.pos = 0;
    this.limit = data.length;
    this.capacity = data.length; // if a capacity field exists
}

