@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != null && !Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }

    // Null values are returned as null
    if (value == null) {
        return null;
    }

    try {
        // If the value is already a Character, return it directly
        if (value instanceof Character) {
            return value;
        }

        // Handle String input: must be a single character
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return Character.valueOf(str.charAt(0));
            } else {
                throw new IllegalArgumentException("Cannot convert String of length " + str.length() + " to Character");
            }
        }

        // Handle Number input: cast to char if within valid range
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            if (intVal < 0 || intVal > 0xFFFF) {
                throw new IllegalArgumentException("Number value " + intVal + " is out of char range");
            }
            return Character.valueOf((char) intVal);
        }

        // Handle Boolean input: not supported for Character conversion
        if (value instanceof Boolean) {
            throw new IllegalArgumentException("Cannot convert Boolean to Character");
        }

        // If none of the above, throw an exception
        throw new IllegalArgumentException("Unsupported type for conversion to Character: " + value.getClass().getName());
    } catch (Exception e) {
        // Wrap any exception into the declared Exception type
        throw new Exception("Failed to convert value to Character: " + value, e);
    }
}

