public final byte[] toByteArray() {
    // If no buffers are present, return an empty array
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }

    // Compute the total length of all buffers
    long totalLength = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            totalLength += buf.length;
        }
    }

    // Guard against integer overflow
    if (totalLength > Integer.MAX_VALUE) {
        throw new IllegalStateException("Total buffer size exceeds maximum array size");
    }

    int total = (int) totalLength;
    byte[] result = new byte[total];
    int pos = 0;

    // Copy each buffer into the result array
    for (byte[] buf : buffers) {
        if (buf != null) {
            System.arraycopy(buf, 0, result, pos, buf.length);
            pos += buf.length;
        }
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5;
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid Unicode escape: \\u" + hex);
                        }
                    } else {
                        throw new IllegalArgumentException("Incomplete Unicode escape at position " + i);
                    }
                    break;
                default:
                    // Octal escape: up to 3 octal digits (0-7)
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = Math.min(j + 3, len);
                        int val = 0;
                        while (j < end && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                            val = (val << 3) + (str.charAt(j) - '0');
                            j++;
                        }
                        sb.append((char) val);
                        i = j - 1;
                    } else {
                        // Unknown escape, keep as is
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

