}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Validate input
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Input sets cannot be null");
    }

    try {
        // Determine the smaller set to iterate over for efficiency
        Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
        Set<V> larger  = set1.size() >  set2.size() ? set1 : set2;

        // Create a new set containing the intersection
        Set<V> result = new java.util.HashSet<>(smaller);
        result.retainAll(larger);
        return result;
    } catch (Exception e) {
        // Wrap any unexpected runtime exception
        throw new RuntimeException("Failed to compute intersection", e);
    }
}

