protected Object filter(Object msg) {
    if (msg == null) {
        return null;
    }
    try {
        Class<?> clazz = Class.forName("BroadcastFilter");
        // Try to invoke a static filter method first
        try {
            java.lang.reflect.Method staticMethod = clazz.getMethod("filter", Object.class);
            if (java.lang.reflect.Modifier.isStatic(staticMethod.getModifiers())) {
                return staticMethod.invoke(null, msg);
            }
        } catch (NoSuchMethodException ignored) {
            // No static method, will try instance method below
        }
        // Fallback to instance method
        Object instance = clazz.getDeclaredConstructor().newInstance();
        java.lang.reflect.Method instanceMethod = clazz.getMethod("filter", Object.class);
        return instanceMethod.invoke(instance, msg);
    } catch (Exception e) {
        throw new RuntimeException("Failed to invoke BroadcastFilter", e);
    }
}

