            }
            String value = pair.getValue();
            if (value != null) {
                json.addProperty(key, value);
            }
            // If value is null, skip adding this key to avoid null entries
        }
    } catch (Exception e) {
        // In case of any unexpected error, return an empty JsonObject
        return new JsonObject();
    }
    return json;
}

protected int removeUnusedNodes() {
    try {
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, remove the entire tree
        if (!root.isActive()) {
            int count = countNodes(root);
            root = null;
            return count;
        }
        // Otherwise, process children recursively
        return removeInactiveChildren(root);
    } catch (Exception e) {
        // In case of unexpected errors, return 0 to indicate no nodes removed
        return 0;
    }
}

private int removeInactiveChildren(Category parent) {
    int removed = 0;
    java.util.List<Category> children = parent.getChildren();
    if (children == null) {
        return 0;
    }
    java.util.Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (child == null) {
            continue;
        }
        if (!child.isActive()) {
            removed += countNodes(child);
            it.remove();
        } else {
            removed += removeInactiveChildren(child);
        }
    }
    return removed;
}

private int countNodes(Category node) {
    if (node == null) {
        return 0;
    }
    int count = 1; // count the node itself
    java.util.List<Category> children = node.getChildren();
    if (children != null) {
        for (Category c : children) {
            count += countNodes(c);
        }
    }
    return count;
}

