final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    try {
        if (constantPoolEntryIndex < 1) {
            throw new IllegalArgumentException("constantPoolEntryIndex must be >= 1");
        }
        // constant pool count is stored at bytes 8 and 9
        int cpCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
        if (constantPoolEntryIndex >= cpCount) {
            throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
        }
        int offset = 10; // start of constant pool
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = classFileBuffer[offset] & 0xFF;
            offset++;
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                    offset += 2 + len;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    i++; // these take up two indices
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                case 15: // CONSTANT_MethodHandle
                    offset += 3;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
            }
        }
        // Now at the target entry
        int tag = classFileBuffer[offset] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Constant pool entry is not a Utf8");
        }
        offset++;
        int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
        offset += 2;
        if (len > charBuffer.length) {
            throw new IllegalArgumentException("Provided charBuffer is too small");
        }
        String result = new String(classFileBuffer, offset, len, "UTF-8");
        result.getChars(0, len, charBuffer, 0);
        return result;
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to read Utf8 constant pool entry", e);
    }
}

private static char decodeHexNibble(final char c) {
    if (c >= '0' && c <= '9') {
        return (char)(c - '0');
