public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    // The largest n for which n! fits in a signed 64‑bit long is 20
    if (n > 20) {
        throw new IllegalArgumentException("n is too large for long factorial");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        // Check for overflow before multiplication
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("Factorial result overflows long");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    if (dir == 0) {
        throw new IllegalArgumentException("Direction must be non-zero");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    try {
        // Check the starting node first
        if (predicate.test(circ.getNode())) {
            return circ;
        }

        // Traverse until we reach the stop node
        while (!circ.getNode().equals(stop)) {
            circ = dir > 0 ? circ.next() : circ.prev();
            if (circ == null) {
                // Unexpected end of traversal; break out
                break;
            }
            if (predicate.test(circ.getNode())) {
                return circ;
            }
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Error during outer face traversal", e);
    }

    // If we exit the loop, either we reached the stop node or traversal failed.
    // Return a circulator positioned at the stop node if possible.
    if (circ != null && circ.getNode().equals(stop)) {
        return circ;
    }
    return new OuterFaceCirculator(stop);
}

public void add(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
