public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this;
    }
    // Ensure capacity for the new data
    int newCapacity = length + byteLength;
    if (buffer == null || buffer.length < newCapacity) {
        int newSize = Math.max(buffer == null ? 32 : buffer.length * 2, newCapacity);
        byte[] newBuffer = new byte[newSize];
        if (buffer != null) {
            System.arraycopy(buffer, 0, newBuffer, 0, length);
        }
        buffer = newBuffer;
    }
    if (byteArrayValue == null) {
        // Fill with zero bytes
        java.util.Arrays.fill(buffer, length, length + byteLength, (byte)0);
    } else {
        if (byteOffset < 0 || byteLength < 0 || byteOffset > byteArrayValue.length - byteLength) {
            throw new IllegalArgumentException("Invalid byteOffset or byteLength");
        }
        System.arraycopy(byteArrayValue, byteOffset, buffer, length, byteLength);
    }
    length += byteLength;
    return this;
}

