public static byte convertHexDigit(byte b) {
    // Check for numeric digits '0' to '9'
    if (b >= '0' && b <= '9') {
        return (byte) (b - '0');
    }
    // Check for lowercase letters 'a' to 'f'
    if (b >= 'a' && b <= 'f') {
        return (byte) (b - 'a' + 10);
    }
    // Check for uppercase letters 'A' to 'F'
    if (b >= 'A' && b <= 'F') {
        return (byte) (b - 'A' + 10);
    }
    // If none of the above, the input is not a valid hex digit
    throw new IllegalArgumentException("Invalid hex digit: " + (char) b);
}

