private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalArgumentException("modelName must not be null or empty");
    }
    int[] indices = shardingKeyIndicesMap.get(modelName);
    if (indices == null || indices.length == 0) {
        throw new IllegalStateException("No sharding key indices defined for model: " + modelName);
    }
    java.util.Arrays.sort(indices);
    for (int i = 1; i < indices.length; i++) {
        if (indices[i] != indices[i - 1] + 1) {
            throw new IllegalStateException(
                "Sharding key indices for model " + modelName + " are not continuous: " +
                java.util.Arrays.toString(indices));
        }
    }
}

public byte readByte() throws IOException {
    // If the buffer is exhausted, refill it from the underlying stream
    if (pos >= count) {
        int bytesRead = in.read(buf, 0, buf.length);
        if (bytesRead <= 0) { // bytesRead == -1 indicates end of stream
            throw new IOException("No more data available");
        }
        pos = 0;
        count = bytesRead;
    }
    // Return the next byte from the buffer
    return buf[pos++];
}

