public double vertexWeight(Set<V> v) {
    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null");
    }
    if (v.isEmpty()) {
        throw new IllegalArgumentException("Vertex set cannot be empty");
    }
    if (v.size() > 1) {
        throw new IllegalArgumentException("Vertex set must contain exactly one vertex");
    }
    V vertex = v.iterator().next();
    double sum = 0.0;
    try {
        for (Edge<V> e : getEdges()) {
            if (e.getTarget().equals(vertex)) {
                sum += e.getWeight();
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute vertex weight", e);
    }
    return sum;
}

public int compare(Object aObj1,Object aObj2){
    // Handle nulls: null is considered less than any non-null value
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }

    // Both objects are non-null
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            throw new IllegalArgumentException(
                "Objects are not mutually comparable: " + aObj1 + " and " + aObj2, e);
        } catch (RuntimeException e) {
            throw new IllegalArgumentException(
                "Comparison failed for objects: " + aObj1 + " and " + aObj2, e);
        }
    } else {
        throw new IllegalArgumentException(
            "Objects do not implement Comparable: " + aObj1 + " and " + aObj2);
    }
}

