protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    // Empty tour: return an empty path
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }

    boolean directed = graph.getType().isDirected();
    Map<V, List<V>> adjacency = new HashMap<>();
    Map<V, Integer> inDeg = new HashMap<>();
    Map<V, Integer> outDeg = new HashMap<>();

    // Build adjacency and degree maps
    for (E e : tour) {
        if (e == null) {
            throw new IllegalArgumentException("Edge in tour is null");
        }
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not in the graph");
        }
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        if (directed) {
            outDeg.put(u, outDeg.getOrDefault(u, 0) + 1);
            inDeg.put(v, inDeg.getOrDefault(v, 0) + 1);
            adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        } else {
            adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
            adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
        }
    }

    // Determine start vertex
    V start = null;
    if (directed) {
        for (V v : adjacency.keySet()) {
            if (outDeg.getOrDefault(v, 0) == 1 && inDeg.getOrDefault(v, 0) == 0) {
                start = v;
                break;
            }
        }
        if (start == null) { // cycle or no clear start
            for (V v : adjacency.keySet()) {
                if (outDeg.getOrDefault(v, 0) > 0) {
                    start = v;
                    break;
                }
            }
        }
    } else {
        for (V v : adjacency.keySet()) {
            if (adjacency.get(v).size() == 1) {
                start = v;
                break;
            }
        }
        if (start == null) { // cycle
            for (V v : adjacency.keySet()) {
                if (!adjacency.get(v).isEmpty()) {
                    start = v;
                    break;
                }
            }
        }
    }

    if (start == null) {
        throw new IllegalArgumentException("Cannot determine a start vertex for the tour");
    }

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();

    V current = start;
    vertexList.add(current);

    while (usedEdges.size() < tour.size()) {
        boolean found = false;
        for (E e : tour) {
            if (usedEdges.contains(e)) {
                continue;
            }
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (directed) {
                if (src.equals(current)) {
                    edgeList.add(e);
                    usedEdges.add(e);
                    current = tgt;
                    vertexList.add(current);
                    found = true;
                    break;
                }
            } else {
                if (src.equals(current) || tgt.equals(current)) {
                    edgeList.add(e);
                    usedEdges.add(e);
                    current = src.equals(current) ? tgt : src;
                    vertexList.add(current);
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Edges do not form a continuous path");
        }
    }

    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

