int addConstantNameAndType(final String name,final String descriptor){
    if(name == null || descriptor == null){
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    if(constantPool == null){
        throw new IllegalStateException("constant pool not initialized");
    }
    // Search for an existing NameAndType constant
    for(int i = 0; i < constantPool.size(); i++){
        Object obj = constantPool.get(i);
        if(obj instanceof ConstantNameAndType_info){
            ConstantNameAndType_info nt = (ConstantNameAndType_info)obj;
            int nameIdx = nt.getNameIndex();
            int descIdx = nt.getDescriptorIndex();
            Object nameObj = constantPool.get(nameIdx);
            Object descObj = constantPool.get(descIdx);
            if(nameObj instanceof ConstantUtf8_info && descObj instanceof ConstantUtf8_info){
                String n = ((ConstantUtf8_info)nameObj).getValue();
                String d = ((ConstantUtf8_info)descObj).getValue();
                if(name.equals(n) && descriptor.equals(d)){
                    return i;
                }
            }
        }
    }
    // Find or add UTF8 entry for name
    int nameIdx = -1;
    for(int i = 0; i < constantPool.size(); i++){
        Object obj = constantPool.get(i);
        if(obj instanceof ConstantUtf8_info){
            String val = ((ConstantUtf8_info)obj).getValue();
            if(name.equals(val)){
                nameIdx = i;
                break;
            }
        }
    }
    if(nameIdx == -1){
        constantPool.add(new ConstantUtf8_info(name));
        nameIdx = constantPool.size() - 1;
    }
    // Find or add UTF8 entry for descriptor
    int descIdx = -1;
    for(int i = 0; i < constantPool.size(); i++){
        Object obj = constantPool.get(i);
        if(obj instanceof ConstantUtf8_info){
            String val = ((ConstantUtf8_info)obj).getValue();
            if(descriptor.equals(val)){
                descIdx = i;
                break;
            }
        }
    }
    if(descIdx == -1){
        constantPool.add(new ConstantUtf8_info(descriptor));
        descIdx = constantPool.size() - 1;
    }
    // Add new NameAndType constant
    constantPool.add(new ConstantNameAndType_info(nameIdx, descIdx));
    return constantPool.size() - 1;
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null as specified
    if (array1 == null && array2 == null) {
        return null;
    }
    // If one of the arrays is null, return a copy of the other array
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }
    // Both arrays are non-null: create a new array to hold all elements
    int len1 = array1.length;
    int len2 = array2.length;
    String[] result = new String[len1 + len2];
    // Copy elements from the first array
    System.arraycopy(array1, 0, result, 0, len1);
    // Copy elements from the second array
    System.arraycopy(array2, 0, result, len1, len2);
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Basic validation
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }

    // Ensure bucket 0 exists
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }

    // Move vertices from minLabel bucket to bucket 0
    for (Integer v : source) {
        if (v == null) {
            continue;
        }
        // Update label if within bounds
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
        target.add(v);
    }

    // Clear the source bucket
    source.clear();
}

