void removeSelf() {
    try {
        // Unlink this bucket from its previous bucket if it exists
        if (prev != null) {
            prev.next = next;
        }
        // Unlink this bucket from its next bucket if it exists
        if (next != null) {
            next.prev = prev;
        }
        // If this bucket is the head of a chain in the hash table, update the table's reference
        if (table != null && index >= 0 && index < table.buckets.length && table.buckets[index] == this) {
            table.buckets[index] = next;
        }
        // Nullify references to aid garbage collection
        prev = null;
        next = null;
        table = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove bucket", e);
    }
}

