private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        prev.next = next;
    } else {
        // node is the head
        head = next;
    }

    if (next != null) {
        next.prev = prev;
    } else {
        // node is the tail
        tail = prev;
    }

    // Help garbage collection
    node.prev = null;
    node.next = null;
    // If the node holds a reference to the element, clear it if desired:
    // node.element = null;

    size--;
    return true;
}

