            throw new NullPointerException("array content is null at index " + i);
        }
        result[i] = c.charValue();
    }
    return result;
}

private String parseToken(final char[] terminators) {
    // Validate terminators
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("terminators cannot be null or empty");
    }
    // Ensure input is available
    if (input == null) {
        return null;
    }
    // Clamp position
    if (pos < 0) {
        pos = 0;
    }
    if (pos > input.length()) {
        pos = input.length();
    }
    int start = pos;
    try {
        while (pos < input.length()) {
            char c = input.charAt(pos);
            boolean isTerminator = false;
            for (char t : terminators) {
                if (c == t) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;
            }
            pos++;
        }
        String token = input.substring(start, pos);
        // Consume terminator if present
        if (pos < input.length()) {
            pos++; // skip terminator
        }
        return token;
    } catch (Exception e) {
        throw new RuntimeException("Error parsing token", e);
    }
}

