private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    long runningSum = 0L;
    int[] suffixArr = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        long v = (val == null) ? 0L : val.longValue();
        runningSum += v;
        suffixArr[i] = (int) runningSum; // cast to int; may overflow if sum exceeds Integer.MAX_VALUE
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(suffixArr[i]);
    }
    return new Pair<>(suffix, runningSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Validate input
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null.");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len) {
        throw new IllegalArgumentException(
            "Indices out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException(
            "Invalid range: from (" + from + ") is greater than to (" + to + ").");
    }

    // Reverse elements in place
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        // Nothing to move if the source is the same as the destination
        return;
    }
    // If the source list is empty, nothing to do
    if (list.head == null) {
        return;
    }

    // Detach the entire source list
    ListNodeImpl<E> srcFirst = list.head;
    ListNodeImpl<E> srcLast  = list.tail;
    int srcSize = list.size;

    // Attach the detached segment to this list
    if (this.head == null) {
        // Destination list is empty
        this.head = srcFirst;
        this.tail = srcLast;
    } else {
        // Destination list is non‑empty
        this.tail.next = srcFirst;
        srcFirst.prev = this.tail;
        this.tail = srcLast;
    }
    this.size += srcSize;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If the prefix is null but the string is not, it's not a match
    if (prefix == null) {
        return false;
    }
    // If the prefix is longer than the string, it cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Use regionMatches for case-insensitive comparison if requested
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

