public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("Source BeanMap cannot be null");
    }
    PropertyDescriptor[] srcDescs = map.getPropertyDescriptors();
    PropertyDescriptor[] destDescs = this.getPropertyDescriptors();
    if (srcDescs == null || destDescs == null) {
        return; // nothing to copy
    }
    // Build a quick lookup for destination descriptors
    java.util.Map<String, PropertyDescriptor> destLookup = new java.util.HashMap<>();
    for (PropertyDescriptor pd : destDescs) {
        destLookup.put(pd.getName(), pd);
    }
    for (PropertyDescriptor srcPd : srcDescs) {
        // Skip write‑only properties in the source
        if (srcPd.getReadMethod() == null) {
            continue;
        }
        PropertyDescriptor destPd = destLookup.get(srcPd.getName());
        if (destPd == null) {
            continue; // property not present in destination
        }
        // Skip read‑only properties in the destination
        if (destPd.getWriteMethod() == null) {
            continue;
        }
        try {
            Object value = map.getProperty(srcPd.getName());
            this.setProperty(destPd.getName(), value);
        } catch (Exception e) {
            throw new IllegalArgumentException(
                "Failed to copy property '" + srcPd.getName() + "'", e);
        }
    }
}

