private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Validate inputs
    if (graph == null || vertices == null) {
        return false;
    }

    // A null or empty set of vertices is trivially a clique
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }

    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }

    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    // Check every unordered pair of vertices
    for (int i = 0; i < n; i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }

    return true;
}

