            throw new IllegalArgumentException("Keys are not comparable", e);
        }
        int predIdx;
        if (idx >= 0) {
            predIdx = idx - 1;
        } else {
            int insertionPoint = -idx - 1;
            predIdx = insertionPoint - 1;
        }
        result.add(predIdx >= 0 ? predIdx : -1);
    }
    return result;
}

