public static boolean equals(Point2D p1, Point2D p2){
    // Define tolerance for floating point comparison
    final double TOLERANCE = 1e-9;
    // If both references are identical, they are equal
    if (p1 == p2) {
        return true;
    }
    // If either point is null, they cannot be equal
    if (p1 == null || p2 == null) {
        return false;
    }
    try {
        double dx = p1.getX() - p2.getX();
        double dy = p1.getY() - p2.getY();
        return Math.abs(dx) <= TOLERANCE && Math.abs(dy) <= TOLERANCE;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, consider points not equal
        return false;
    }
}

