public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    boolean absolute = path.startsWith("/");
    Deque<String> stack = new ArrayDeque<>();

    // Process the base path
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            } else if (!absolute) {
                // For relative base path, keep leading ".."
                stack.push("..");
            }
        } else {
            stack.push(part);
        }
    }

    // Process the relative path
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            } else if (!absolute) {
                stack.push("..");
            }
        } else {
            stack.push(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (absolute) {
        result.append("/");
    }

    // Since we used a stack, we need to reverse the order
    Iterator<String> it = stack.descendingIterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If the result is empty and not absolute, return "."
    if (result.length() == 0) {
        return absolute ? "/" : ".";
    }

    return result.toString();
}

