static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object o : array) {
        if (o != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        // All elements are non‑null; safe to cast back to String[]
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // Fallback: create a new array if the original is not a String[]
            String[] result = new String[nonNullCount];
            for (int i = 0; i < array.length; i++) {
                result[i] = (String) array[i];
            }
            return result;
        }
    }
    if (nonNullCount == 0) {
        return new String[0];
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            try {
                result[idx++] = (String) o;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Array contains non-String element", e);
            }
        }
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSlash = filename.lastIndexOf('/');
    int lastBackslash = filename.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSlash, lastBackslash);
    if (lastSeparator > lastDot) {
        return -1;
    }
    return lastDot;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        long currentTime = System.currentTimeMillis();
        // If the timestamp is in the future, it cannot be expired yet.
        if (timestamp > currentTime) {
            return false;
        }
        // If the threshold is non-positive, consider it expired immediately.
        if (expiredThreshold <= 0) {
            return true;
        }
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, conservatively do not expire.
        return false;
    }
}

Edge edgeToNext() {
    try {
        // Ensure we have a previous and a next node to connect
        if (previousNode == null || nextNode == null) {
            throw new IllegalStateException("Cannot create edge: previous or next node is null");
        }

        // Resolve virtual nodes to their real counterparts
        Node from = previousNode.isVirtual() ? previousNode.getRealNode() : previousNode;
        Node to   = nextNode.isVirtual()    ? nextNode.getRealNode()    : nextNode;

        // If the nodes are the same, no edge is needed
        if (from == to) {
            return null;
        }

        // Create and return the edge
        return new Edge(from, to);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Failed to create edge to next node", e);
    }
}

