    // Handle null inputs
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();

    // Empty substring matches at any valid index
    if (subLen == 0) {
        return index >= 0 && index <= strLen;
    }

    // Index must be within bounds to accommodate the substring
    if (index < 0 || index + subLen > strLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getRenderedMessage();
    if (message == null) {
        return;
    }
    if (clients == null) {
        return;
    }
    synchronized (clients) {
        java.util.Iterator<Socket> it = clients.iterator();
        while (it.hasNext()) {
            Socket client = it.next();
            if (client == null) {
                it.remove();
                continue;
            }
            try {
                if (client.isClosed()) {
                    it.remove();
                    client.close();
                    continue;
                }
                java.io.OutputStream out = client.getOutputStream();
                if (out == null) {
                    it.remove();
                    client.close();
                    continue;
                }
                out.write(message.getBytes());
                out.flush();
            } catch (java.io.IOException e) {
                it.remove();
                try {
                    client.close();
                } catch (java.io.IOException ex) {
                    // ignore
                }
            }
        }
    }
}

public static String toString(final char ch) {
    // For ASCII 7-bit characters, a cache could be used to return the same String instance.
    // Here we simply return the String representation of the character.
    return String.valueOf(ch);
}

private void checkIfPackedField() throws IOException {
    // Extract the field number and wire type from the current tag.
    int fieldNumber = currentTag >>> 3;
    int wireType = currentTag & 0x7;

    // Packed repeated fields are encoded as length‑delimited (wire type 2).
    if (wireType == 2) {
        // Read the length of the packed data.
        int length = input.readRawVarint32();

        // Push a new limit so that we only read the packed data.
        packedLimit = input.pushLimit(length);

        // Record that we are currently reading a packed field.
        packed = true;
        packedFieldNumber = fieldNumber;
    } else {
        // Not a packed field.
        packed = false;
    }
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            // EOF reached before any bytes were read
            if (shift == 0) {
                return 0;
            }
            // EOF in the middle of a varint is an error
            throw new IOException("EOF reached while reading varint");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed varint");
        }
    }
}

final ByteVector put11(final int byteValue1,final int byteValue2){
    // Validate input byte values (0-255)
    if(byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255){
        throw new IllegalArgumentException("byte values must be in the range 0-255");
    }
    // Ensure the internal buffer exists and has enough space
    if (buf == null) {
        buf = new byte[2];
    } else if (pos + 2 > buf.length) {
        int newCap = Math.max(buf.length * 2, pos + 2);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    // Insert the two bytes
    buf[pos++] = (byte) byteValue1;
    buf[pos++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    try {
        // Assume the class has fields: startByte, endByte, totalSize
        if (startByte < 0 || endByte < 0 || startByte > endByte) {
            throw new IllegalArgumentException("Invalid byte range: startByte=" + startByte + ", endByte=" + endByte);
        }
        String totalStr = (totalSize > 0) ? Long.toString(totalSize) : "*";
        return "bytes " + startByte + "-" + endByte + "/" + totalStr;
    } catch (Exception e) {
        // Wrap any unexpected exception in a RuntimeException to avoid leaking implementation details
        throw new RuntimeException("Failed to build Content-Range header", e);
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parseFromString(line);
            } catch (Exception e) {
                // Skip malformed line
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            long ts = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStartTime();
                long end = range.getEndTime();
                if (ts >= start && ts <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}
